begin;
alter table public.identity_audit_events drop constraint if exists identity_audit_events_event_type_check;
alter table public.identity_audit_events add constraint identity_audit_events_event_type_check check(event_type in('login','logout','password.changed','password.reset','email.verified','email.changed','mfa.enabled','mfa.disabled','device.trusted','device.removed','session.revoked','token.created','token.revoked','organization.switched','workspace.created','organization.created','google.connected','profile.updated','invitation.created'));
create table if not exists public.identity_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id)on delete cascade,organization_id uuid references public.organizations(id),workspace_id uuid references public.workspaces(id),session_fingerprint text not null,device_name text not null default'Unknown device',ip_hash text,user_agent text,last_seen_at timestamptz not null default now(),expires_at timestamptz not null,revoked_at timestamptz,created_at timestamptz not null default now(),unique(user_id,session_fingerprint));
create table if not exists public.trusted_devices(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id)on delete cascade,organization_id uuid references public.organizations(id),workspace_id uuid references public.workspaces(id),device_fingerprint text not null,device_name text not null,trusted_at timestamptz not null default now(),last_seen_at timestamptz not null default now(),expires_at timestamptz not null,removed_at timestamptz,unique(user_id,device_fingerprint));
create table if not exists public.security_alerts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id)on delete cascade,organization_id uuid references public.organizations(id),workspace_id uuid references public.workspaces(id),alert_type text not null,severity text not null check(severity in('low','medium','high','critical')),title text not null,details jsonb not null default'{}',resolved_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.authentication_attempts(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id)on delete cascade,email_hash text not null,outcome text not null check(outcome in('success','failure','locked')),auth_method text not null,latency_ms integer not null check(latency_ms>=0),mfa_used boolean not null default false,ip_hash text,user_agent text,occurred_at timestamptz not null default now());
create table if not exists public.personal_access_tokens(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id)on delete cascade,organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),name text not null check(char_length(name)between 1 and 100),token_prefix text not null,token_hash text unique not null,scopes text[]not null default'{}',expires_at timestamptz,last_used_at timestamptz,revoked_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.mfa_recovery_codes(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id)on delete cascade,code_hash text not null,used_at timestamptz,created_at timestamptz not null default now(),unique(user_id,code_hash));
create table if not exists public.user_organization_context(user_id uuid primary key references auth.users(id)on delete cascade,organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),switched_at timestamptz not null default now());
create index if not exists identity_sessions_active_idx on public.identity_sessions(user_id,last_seen_at desc)where revoked_at is null;create index if not exists auth_attempts_user_time_idx on public.authentication_attempts(user_id,occurred_at desc);create index if not exists pat_scope_idx on public.personal_access_tokens(user_id,organization_id,workspace_id)where revoked_at is null;create index if not exists security_alert_user_time_idx on public.security_alerts(user_id,created_at desc)where resolved_at is null;
alter table public.identity_sessions enable row level security;alter table public.trusted_devices enable row level security;alter table public.security_alerts enable row level security;alter table public.authentication_attempts enable row level security;alter table public.personal_access_tokens enable row level security;alter table public.mfa_recovery_codes enable row level security;alter table public.user_organization_context enable row level security;
create policy "identity_session_owner" on public.identity_sessions for select to authenticated using(user_id=auth.uid());create policy "trusted_device_owner" on public.trusted_devices for select to authenticated using(user_id=auth.uid());create policy "security_alert_owner" on public.security_alerts for select to authenticated using(user_id=auth.uid());create policy "authentication_attempt_owner" on public.authentication_attempts for select to authenticated using(user_id=auth.uid());create policy "pat_owner_read" on public.personal_access_tokens for select to authenticated using(user_id=auth.uid()and public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null);create policy "recovery_code_owner" on public.mfa_recovery_codes for select to authenticated using(user_id=auth.uid());create policy "organization_context_owner" on public.user_organization_context for select to authenticated using(user_id=auth.uid()and public.is_organization_member(organization_id));
create or replace function public.switch_current_organization(p_organization_id uuid,p_workspace_id uuid)returns void language plpgsql security definer set search_path=public as $$begin if not exists(select 1 from organization_members where organization_id=p_organization_id and user_id=auth.uid()and status='active')or not exists(select 1 from workspace_members where organization_id=p_organization_id and workspace_id=p_workspace_id and user_id=auth.uid()and status='active')then raise exception'invalid organization membership';end if;insert into user_organization_context(user_id,organization_id,workspace_id)values(auth.uid(),p_organization_id,p_workspace_id)on conflict(user_id)do update set organization_id=excluded.organization_id,workspace_id=excluded.workspace_id,switched_at=now();insert into identity_audit_events(organization_id,workspace_id,user_id,event_type,metadata)values(p_organization_id,p_workspace_id,auth.uid(),'organization.switched','{}');end$$;
create or replace function public.create_personal_access_token(p_workspace_id uuid,p_name text,p_token_prefix text,p_token_hash text,p_scopes text[],p_expires_at timestamptz)returns uuid language plpgsql security definer set search_path=public as $$declare v_org uuid;v_id uuid;begin select organization_id into v_org from workspace_members where workspace_id=p_workspace_id and user_id=auth.uid()and status='active';if v_org is null or array_length(p_scopes,1)>20 or p_expires_at is not null and p_expires_at<=now()then raise exception'invalid token request';end if;insert into personal_access_tokens(user_id,organization_id,workspace_id,name,token_prefix,token_hash,scopes,expires_at)values(auth.uid(),v_org,p_workspace_id,trim(p_name),p_token_prefix,p_token_hash,p_scopes,p_expires_at)returning id into v_id;insert into identity_audit_events(organization_id,workspace_id,user_id,event_type,metadata)values(v_org,p_workspace_id,auth.uid(),'token.created',jsonb_build_object('token_id',v_id,'scopes',p_scopes));return v_id;end$$;
create or replace function public.revoke_personal_access_token(p_token_id uuid)returns void language plpgsql security definer set search_path=public as $$declare t personal_access_tokens%rowtype;begin select*into t from personal_access_tokens where id=p_token_id and user_id=auth.uid()and revoked_at is null for update;if not found then raise exception'token not found';end if;update personal_access_tokens set revoked_at=now()where id=t.id;insert into identity_audit_events(organization_id,workspace_id,user_id,event_type,metadata)values(t.organization_id,t.workspace_id,auth.uid(),'token.revoked',jsonb_build_object('token_id',t.id));end$$;
create or replace function public.record_identity_audit(p_event_type text,p_organization_id uuid default null,p_workspace_id uuid default null,p_outcome text default'success',p_metadata jsonb default'{}')returns uuid language plpgsql security definer set search_path=public as $$declare v_id uuid;begin if auth.uid()is null then raise exception'authentication required';end if;if p_event_type not in('login','logout','password.changed','password.reset','email.verified','email.changed','mfa.enabled','mfa.disabled','device.trusted','device.removed','session.revoked','token.created','token.revoked','organization.switched','workspace.created','organization.created','google.connected','profile.updated','invitation.created')then raise exception'invalid audit event';end if;if p_organization_id is not null and not is_organization_member(p_organization_id)then raise exception'invalid audit tenant';end if;insert into identity_audit_events(organization_id,workspace_id,user_id,event_type,outcome,metadata)values(p_organization_id,p_workspace_id,auth.uid(),p_event_type,p_outcome,coalesce(p_metadata,'{}'))returning id into v_id;return v_id;end$$;
create or replace function public.record_authentication_attempt(p_email_hash text,p_outcome text,p_method text,p_latency_ms integer,p_mfa_used boolean default false,p_ip_hash text default null,p_user_agent text default null)returns void language plpgsql security definer set search_path=public as $$declare v_failures integer;begin if p_outcome not in('success','failure','locked')or p_latency_ms<0 then raise exception'invalid attempt';end if;insert into authentication_attempts(user_id,email_hash,outcome,auth_method,latency_ms,mfa_used,ip_hash,user_agent)values(auth.uid(),p_email_hash,p_outcome,p_method,p_latency_ms,p_mfa_used,p_ip_hash,left(p_user_agent,500));select count(*)into v_failures from authentication_attempts where email_hash=p_email_hash and outcome='failure'and occurred_at>now()-interval'15 minutes';if v_failures>=5 and auth.uid()is not null then insert into security_alerts(user_id,alert_type,severity,title,details)values(auth.uid(),'suspicious_login','high','Repeated failed login attempts detected',jsonb_build_object('attempts',v_failures));end if;end$$;
create or replace function public.check_auth_rate_limit(p_email_hash text)returns boolean language sql security definer set search_path=public as $$select count(*)<5 from authentication_attempts where email_hash=p_email_hash and outcome='failure'and occurred_at>now()-interval'15 minutes'$$;
create or replace function public.replace_mfa_recovery_codes(p_code_hashes text[])returns void language plpgsql security definer set search_path=public as $$begin if auth.uid()is null or array_length(p_code_hashes,1)<>10 then raise exception'invalid recovery codes';end if;delete from mfa_recovery_codes where user_id=auth.uid();insert into mfa_recovery_codes(user_id,code_hash)select auth.uid(),unnest(p_code_hashes);end$$;
create or replace function public.revoke_other_identity_sessions()returns void language plpgsql security definer set search_path=public as $$begin update identity_sessions set revoked_at=now()where user_id=auth.uid()and revoked_at is null;end$$;
create or replace function public.trust_identity_device(p_fingerprint text,p_name text)returns uuid language plpgsql security definer set search_path=public as $$declare v_id uuid;begin insert into trusted_devices(user_id,organization_id,workspace_id,device_fingerprint,device_name,expires_at)select auth.uid(),organization_id,workspace_id,p_fingerprint,left(p_name,100),now()+interval'90 days'from user_organization_context where user_id=auth.uid()on conflict(user_id,device_fingerprint)do update set device_name=excluded.device_name,last_seen_at=now(),expires_at=excluded.expires_at,removed_at=null returning id into v_id;return v_id;end$$;
create or replace function public.remove_identity_device(p_device_id uuid)returns void language plpgsql security definer set search_path=public as $$begin update trusted_devices set removed_at=now()where id=p_device_id and user_id=auth.uid()and removed_at is null;if not found then raise exception'device not found';end if;end$$;
create or replace function public.upsert_identity_session(p_fingerprint text,p_device_name text,p_ip_hash text,p_user_agent text,p_expires_at timestamptz)returns uuid language plpgsql security definer set search_path=public as $$declare v_id uuid;v_org uuid;v_workspace uuid;begin select organization_id,workspace_id into v_org,v_workspace from user_organization_context where user_id=auth.uid();insert into identity_sessions(user_id,organization_id,workspace_id,session_fingerprint,device_name,ip_hash,user_agent,expires_at)values(auth.uid(),v_org,v_workspace,p_fingerprint,left(p_device_name,100),p_ip_hash,left(p_user_agent,500),p_expires_at)on conflict(user_id,session_fingerprint)do update set last_seen_at=now(),expires_at=excluded.expires_at,revoked_at=null returning id into v_id;return v_id;end$$;
revoke all on function public.switch_current_organization(uuid,uuid),public.create_personal_access_token(uuid,text,text,text,text[],timestamptz),public.revoke_personal_access_token(uuid),public.record_authentication_attempt(text,text,text,integer,boolean,text,text),public.check_auth_rate_limit(text),public.replace_mfa_recovery_codes(text[]),public.revoke_other_identity_sessions(),public.trust_identity_device(text,text),public.remove_identity_device(uuid),public.upsert_identity_session(text,text,text,text,timestamptz)from public;grant execute on function public.switch_current_organization(uuid,uuid),public.create_personal_access_token(uuid,text,text,text,text[],timestamptz),public.revoke_personal_access_token(uuid),public.replace_mfa_recovery_codes(text[]),public.revoke_other_identity_sessions(),public.trust_identity_device(text,text),public.remove_identity_device(uuid),public.upsert_identity_session(text,text,text,text,timestamptz)to authenticated;grant execute on function public.record_authentication_attempt(text,text,text,integer,boolean,text,text),public.check_auth_rate_limit(text)to anon,authenticated;
commit;
